/*******************************************************************************
 * @file    board_config.h
 * @brief   Single place mapping this project's logical devices to the
 *          XPAR_* symbols generated by Vitis from the Vivado block design
 *          (xparameters.h), plus the few analog/timing constants that are
 *          NOT visible from xparameters.h and had to be assumed. Every
 *          assumption is called out with TODO(confirm) - please check these
 *          against the real schematic/BOM before first power-on.
 *
 *          Peripheral inventory (cross-checked against the xparameters.h
 *          you supplied):
 *
 *          RS232_AC_PWR   XUartNs550, DEVICE_ID=XPAR_RS232_AC_PWR_DEVICE_ID
 *          RS232_DC_PWR   XUartNs550, DEVICE_ID=XPAR_RS232_DC_PWR_DEVICE_ID
 *          RS422_PC       XUartNs550, DEVICE_ID=XPAR_RS422_PC_DEVICE_ID
 *          LE1/LE2/LE3    XGpio (1-bit), latch-enable for the 3x F1956
 *                         attenuators, all three share the PSU_SPI_0 MOSI/
 *                         SCLK lines (data shifted to all 3 in parallel,
 *                         LEx selects which one latches - see
 *                         device_attenuator.c).
 *          TTL_DELAY      XGpio (2-bit), selects the optical delay line
 *                         state (0/100/270/400 ns).
 *          PSU_SPI_0      XSpiPs (Zynq MPSoC hardened SPI0), SHARED between
 *                         the AD9361 (main.c, via the no-OS xilinx_spi
 *                         platform layer) and the 3x F1956
 *                         attenuators (device_attenuator.c, direct XSpiPs
 *                         calls) - two independent driver stacks on one
 *                         physical controller. F1956 uses LEx as an
 *                         external latch strobe, not the SPI controller's
 *                         own hardware slave-select, so AD9361 can use the
 *                         SPI0 hardware SS/CS0 line without electrically
 *                         conflicting with attenuator writes - but neither
 *                         driver reprograms the controller's mode/clock
 *                         before each transfer, so whichever one initializes
 *                         LAST is what the bus is actually configured for.
 *                         main.c therefore calls Ad9361_Bringup() BEFORE
 *                         BoardApp_Init() (which calls Attenuator_Init()
 *                         first thing) so the F1956's settings are what's
 *                         live for the rest of the program's life - see
 *                         board_app.c's SHARED-SPI-BUS NOTE. Do not reorder
 *                         those two calls, and re-review this if a future
 *                         change makes AD9361 issue SPI transfers again at
 *                         runtime (e.g. Phase 2 wiring live frequency/gain
 *                         changes into the dispatcher).
 *          SPI_0 (fabric) XSpi (AXI Quad SPI soft core), base
 *                         XPAR_SPI_0_BASEADDR = 0x80000000, 1 slave-select
 *                         line (XPAR_SPI_0_NUM_SS_BITS=1), 8-bit transfer
 *                         width. Confirmed with you (2026-09-07) as the bus
 *                         the ADC7928 is wired to - its SS0 output goes to
 *                         ADC7928 CS. This core existed in xparameters.h
 *                         already but was unused by any reference source,
 *                         which matches your answer that ADC7928 is new.
 *
 *          TODO(confirm): ADC7928 analog front-end. This firmware reports
 *          raw 12-bit codes (0..4095) for all 8 channels; converting a code
 *          to the real "điện áp kích nổ" (detonator/EED trigger voltage,
 *          which is very likely tens to hundreds of volts, i.e. far above
 *          any ADC input range) requires the resistor-divider ratio of the
 *          actual analog front-end, which is not in any document supplied.
 *          ADC7928_VREF_VOLTS / ADC7928_CH_DIVIDER_RATIO below are
 *          placeholders (ratio = 1.0, i.e. "no scaling") - fix these once
 *          the analog front-end schematic is available, or do the
 *          volts-per-code scaling app-side once the real ratio is known
 *          (the firmware always sends the untouched raw ADC code so no
 *          firmware rebuild is required to correct the scaling later).
 ******************************************************************************/
#ifndef BOARD_CONFIG_H
#define BOARD_CONFIG_H

#include "xparameters.h"

/* ---------------- GPIO (latch-enable / delay select) -------------------- */
#define GPIO_LE_ID_1        XPAR_LE1_DEVICE_ID
#define GPIO_LE_ID_2        XPAR_LE2_DEVICE_ID
#define GPIO_LE_ID_3        XPAR_LE3_DEVICE_ID
#define GPIO_DELAY_ID       XPAR_TTL_DELAY_DEVICE_ID

/* ---------------- SPI0 (PS hardened) - F1956 attenuators ---------------- */
#define ATT_SPI_DEVICE_ID   XPAR_PSU_SPI_0_DEVICE_ID

/* ---------------- SPI0 (fabric AXI Quad SPI) - ADC7928 ------------------ */
#define ADC7928_SPI_DEVICE_ID  XPAR_SPI_0_DEVICE_ID
#define ADC7928_SLAVE_SELECT   0x01U   /* only SS0 exists (NUM_SS_BITS=1)   */

/* ---------------- UARTs -------------------------------------------------- *
 * IMPORTANT FINDING vs. the reference src_att_pwr_odly/main.cpp: that code
 * assumes all 3 UartNs550 cores have their interrupt line wired to the GIC
 * (XPAR_FABRIC_..._IP2INTC_IRPT_INTR for each). The xparameters.h you
 * supplied does NOT define any of those 3 macros - the only fabric
 * interrupts it wires to psu_acpu_gic are the two AD9361 DMA IRQs
 * (XPAR_FABRIC_AXI_AD9361_{DAC,ADC}_DMA_IRQ_INTR). Either this
 * xparameters.h predates a later Vivado revision that does wire them, or
 * the UARTs were never meant to interrupt the GIC. Rather than guess, this
 * firmware auto-detects at compile time (see UART_PC_HAS_INTR below) and
 * falls back to polling the RS422/PC link when the interrupt is absent, so
 * it builds and runs either way - but please confirm which is actually
 * true for your board, because polling is adequate but strictly less
 * robust than interrupt-driven RX for a CRC-framed binary protocol under
 * CPU load. The AC/DC supply UARTs are initialized without interrupt; their
 * replies (readback/confirmation, see "AC/DC supply READBACK" below) are
 * read by polling from BoardApp_ServiceRx() - at 9600 baud the 16-byte RX
 * FIFO lasts ~16 ms, far longer than any gap between polls. */
#define UART_AC_PWR_DEVICE_ID    XPAR_RS232_AC_PWR_DEVICE_ID
#define UART_DC_PWR_DEVICE_ID    XPAR_RS232_DC_PWR_DEVICE_ID
#define UART_PC_DEVICE_ID        XPAR_RS422_PC_DEVICE_ID

#ifdef XPAR_FABRIC_RS422_PC_IP2INTC_IRPT_INTR
#define UART_PC_HAS_INTR   1
#define UART_PC_INTR_ID    XPAR_FABRIC_RS422_PC_IP2INTC_IRPT_INTR
#else
#define UART_PC_HAS_INTR   0
#define UART_PC_INTR_ID    0U  /* unused when UART_PC_HAS_INTR == 0 */
#endif

#define UART_AC_PWR_BAUDRATE	 9600U
#define UART_DC_PWR_BAUDRATE	 9600U
#define UART_PC_BAUDRATE         115200U  /* keep in sync with Qt app default */

/* ---------------- AC / DC power supply limits (from validated ref code) - */
#define AC_UVP_VOLTAGE      80.00f
#define AC_MAX_CURRENT      5.00f
#define AC_OVP_LIMIT        150.00f
#define AC_OCP_LIMIT        3.00f

#define DC_MAX_VOLTAGE      36.00f
#define DC_MAX_CURRENT      5.00f
#define DC_OVP_LIMIT        50.00f
#define DC_OCP_LIMIT        3.00f

/* ---------------- AC/DC supply READBACK / confirmation -------------------
 * Every string the firmware sends to the two bench supplies lives here, so
 * a syntax difference found on the bench is a one-line change + rebuild.
 * Terminator "\r\n" is appended by device_power.c - do NOT add it here.
 *
 * AC = ITECH IT-M7700 (SCPI). Set sequence (unchanged, bench-verified):
 *   SYST:REM, PROT:MODE AC, NORM:VOLT:AC <v>, NORM:FREQ <f>, OUTP ON|OFF.
 * Confirmation after a set / on a "refresh" request:
 *   SYST:ERR?  -> "<code>,<text>" (or "+0"); code 0 = no error. The queue is
 *                 drained BEFORE a set so an old error cannot fail a new one.
 *   OUTP?      -> ON|OFF (1|0 also accepted) - must equal the requested state.
 *   MEAS:VOLT? / MEAS:CURR? (operator-specified) and MEAS:FREQ? -> number.
 *   The IT-M7700 programming guide also lists MEAS:VOLT:AC? / MEAS:CURR:AC?;
 *   if the short form is rejected on the bench (SYST:ERR? then reports it
 *   and the app shows the error code), switch the two macros below.
 *
 * DC = Matsusada ("#0 ..." addressed ASCII). Readback per the command table
 * the operator supplied (2026-10-05): MVO? = measured output voltage,
 * MCI? = measured output current, with the same "#0 " address prefix as
 * every other DC command. Replies are parsed by taking the LAST number in
 * the line, so "12.34", "#0 12.34", "+1.234E+01" and "12.34V" all work.
 * NOTE: the set commands are deliberately UNCHANGED (operator decision):
 * VCN/ICN as % of full scale + SW1/SW0. The same table lists LON/LOF and
 * VCN/ICN in real volts/amps - switching to that needs the VALUE scaling in
 * device_power.c changed too, not only the command names (sending the %
 * value to a volts command would set e.g. 66.67 V instead of 24 V). DC_CMD_QUERY_OUTPUT is left empty
 * (no output-state query known) -> DC is "confirmed" when it answers the
 * readback queries right after a set; fill it in (e.g. a status command
 * answering ON/OFF or 1/0) once the manual is available. */
#define AC_CMD_REMOTE           "SYST:REM"
#define AC_CMD_MODE             "PROT:MODE AC"
#define AC_CMD_QUERY_ERROR      "SYST:ERR?"
#define AC_CMD_QUERY_OUTPUT     "OUTP?"
#define AC_CMD_MEAS_VOLT        "MEAS:VOLT?"
#define AC_CMD_MEAS_CURR        "MEAS:CURR?"
#define AC_CMD_MEAS_FREQ        "MEAS:FREQ?"

#define DC_CMD_REMOTE           "#0 REN"
#define DC_CMD_MEAS_VOLT        "#0 MVO?"
#define DC_CMD_MEAS_CURR        "#0 MCI?"
#define DC_CMD_QUERY_OUTPUT     ""          /* "" = not available */

/* Timing. Per-query reply timeout; the first query that times out ends the
 * transaction (result "no reply") instead of waiting out every remaining
 * one. IT-M7700 rule: the complete reply must be received before the next
 * command is sent - the firmware never has more than one query in flight
 * per supply. */
#define PWR_REPLY_TIMEOUT_MS    500U
#define PWR_INTER_CMD_GAP_MS    20U     /* after a reply, before next command */
#define PWR_WRITE_GAP_MS        50U     /* after a write-only command (same
                                         * pacing as the verified sequence)  */
#define PWR_ERR_DRAIN_MAX       20U     /* IT-M7700 error queue depth (20)   */

/* ---------------- F1956 attenuator (datasheet-confirmed) ----------------
 * Renesas/IDT F1956, 7-bit, 0.25 dB/step, 0..31.75 dB, LE min pulse 30 ns,
 * data/LE setup & hold 10 ns. See device_attenuator.c for the serial
 * shift-register framing used to hit those numbers safely. */
#define ATT_STEP_DB         0.25f
#define ATT_MAX_DB          31.75f
#define ATT_MAX_STEPS       127U

/* ---------------- ADC7928 (datasheet-confirmed) --------------------------
 * Analog Devices AD7928 family, 8ch/12-bit, CS active low, DIN/DOUT clocked
 * on SCLK falling edge (CPOL=0, CPHA=1), 20 MHz max SCLK, 16 SCLK/cycle,
 * 1-cycle result latency (result for channel N is only valid on the NEXT
 * 16-clock transfer after N was selected) - see device_adc7928.c. */
#define ADC7928_NUM_CHANNELS    8U
#define ADC7928_VREF_VOLTS      2.5f   /* TODO(confirm): on-chip vs external ref */
#define ADC7928_RANGE_0_TO_2VREF 1     /* 1 = RANGE bit 0 (0..2*VREF), 0 = RANGE bit 1 (0..VREF) */

/* volts-per-LSB scaling per channel = ADC7928_VREF_VOLTS(*2 if RANGE0) / 4096
 * divided again by this per-channel resistor-divider ratio.
 * TODO(confirm): all ratios are placeholders (no scaling) until the analog
 * front-end schematic (especially the "kich no"/EED trigger-voltage input,
 * channel 0 by convention here) is provided. */
#define ADC7928_CH_DIVIDER_RATIO { 1.0f, 1.0f, 1.0f, 1.0f, 1.0f, 1.0f, 1.0f, 1.0f }

/* ---------------- Optical delay line states ------------------------------ */
typedef enum {
    ODLY_0NS   = 0,
    ODLY_270NS = 1,
    ODLY_100NS = 2,
    ODLY_400NS = 3
} Delay_value;
/* NOTE: enum values intentionally match src_att_pwr_odly/main.cpp's ordering
 * (0,270,100,400) exactly - that ordering is what has already been
 * validated against the real optical delay module's GPIO truth table, so
 * it is preserved verbatim rather than "cleaned up" to numeric order. */

#endif /* BOARD_CONFIG_H */
